SELECT * 
FROM customer_behaviour 
LIMIT 20;


-- Q1: What is the total revenue generated by male and female customers?
SELECT 
    gender, 
    SUM(purchase_amount) AS revenue
FROM customer_behaviour
GROUP BY gender;


-- Q2: Which customers used a discount but still spent more than the average purchase amount?
SELECT 
    customer_id, 
    purchase_amount
FROM customer_behaviour
WHERE discount_applied = 'Yes'
  AND purchase_amount >= (
      SELECT AVG(purchase_amount)
      FROM customer_behaviour
  );


-- Q3: Which are the top 5 products purchased with the highest review rating?
SELECT
    item_purchased,
    ROUND(AVG(review_rating)::numeric, 2) AS "Average Product Rating"
FROM customer_behaviour
GROUP BY item_purchased
ORDER BY "Average Product Rating" DESC
LIMIT 5;


-- Q4: Compare average amounts between standard and express shipping.
SELECT
    shipping_type,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase_amount
FROM customer_behaviour
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type;


-- Q5: Do subscribed customers spend more?
-- Compare average and total revenue between subscribers and non-subscribers.
SELECT
    subscription_status,
    COUNT(customer_id) AS total_customers,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_spend,
    ROUND(SUM(purchase_amount)::numeric, 2) AS total_revenue
FROM customer_behaviour
GROUP BY subscription_status
ORDER BY total_revenue DESC, avg_spend DESC;


-- Q6: Which 5 products have the highest percentage of purchases
-- with discounts applied?
SELECT 
    item_purchased,
    ROUND(
        SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) 
        * 100.0 / COUNT(*),
        2
    ) AS discount_rate
FROM customer_behaviour
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;


-- Q7: Segment customers into New, Returning, and Loyal
-- based on their previous purchases.
WITH customer_type AS (
    SELECT 
        customer_id,
        previous_purchases,
        CASE 
            WHEN previous_purchases = 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_segment
    FROM customer_behaviour
)
SELECT 
    customer_segment,
    COUNT(*) AS "Number of Customers"
FROM customer_type
GROUP BY customer_segment;


-- Q8: What are the top 3 most purchased products within each category?
WITH item_counts AS (
    SELECT
        category,
        item_purchased,
        COUNT(customer_id) AS total_orders,
        ROW_NUMBER() OVER (
            PARTITION BY category
            ORDER BY COUNT(customer_id) DESC
        ) AS item_rank
    FROM customer_behaviour
    GROUP BY category, item_purchased
)
SELECT
    item_rank,
    category,
    item_purchased,
    total_orders
FROM item_counts
WHERE item_rank <= 3
ORDER BY category, item_rank;

--Q9  Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT subscription_status,
       COUNT(customer_id) AS repeat_buyers
FROM customer_behaviour
WHERE previous_purchases > 5
GROUP BY subscription_status;

--Q10. What is the revenue contribution of each age group? 
SELECT 
    age_group,
    SUM(purchase_amount) AS total_revenue
FROM customer_behaviour
GROUP BY age_group
ORDER BY total_revenue desc;

SELECT *
FROM customer_behaviour
LIMIT 20;
